namespace NotificationsApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = new();
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed with initial fake data
        _notifications.Add(new(NextId(), "Welcome to the app!", DateTime.UtcNow.AddMinutes(-30)));
        _notifications.Add(new(NextId(), "Your profile was updated.", DateTime.UtcNow.AddMinutes(-15)));
        _notifications.Add(new(NextId(), "New feature: dark mode is available.", DateTime.UtcNow.AddMinutes(-5)));
    }

    /// <summary>Returns all notifications.</summary>
    public List<Notification> GetNotifications()
    {
        lock (_lock)
        {
            return _notifications.ToList();
        }
    }

    /// <summary>Returns notifications added after the given ID.</summary>
    public List<Notification> GetNotificationsSince(int lastSeenId)
    {
        lock (_lock)
        {
            return _notifications.Where(n => n.Id > lastSeenId).ToList();
        }
    }

    /// <summary>Simulates a new notification arriving roughly every 10 seconds.</summary>
    public void SimulateNewNotifications()
    {
        if (Random.Shared.NextDouble() < 0.5)
        {
            lock (_lock)
            {
                var messages = new[]
                {
                    "You have a new follower.",
                    "Someone commented on your post.",
                    "System maintenance scheduled.",
                    "Your report is ready to download.",
                    "A team member mentioned you."
                };
                var msg = messages[Random.Shared.Next(messages.Length)];
                _notifications.Add(new(NextId(), msg, DateTime.UtcNow));
            }
        }
    }

    private int NextId() => _nextId++;
}

@page "/notifications"
@rendermode InteractiveServer
@implements IDisposable
@inject NotificationsApp.Services.NotificationService NotificationService

<PageTitle>Notifications</PageTitle>

<h1>Notifications</h1>

@if (notifications is null)
{
    <p><em>Loading…</em></p>
}
else
{
    <p>
        <span class="badge bg-primary rounded-pill">@notifications.Count</span>
        notification@(notifications.Count != 1 ? "s" : "")
    </p>

    <ul class="list-group">
        @foreach (var n in notifications.OrderByDescending(x => x.Timestamp))
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <span>@n.Message</span>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    [PersistentState]
    public List<NotificationsApp.Services.Notification>? notifications { get; set; }

    private CancellationTokenSource? _cts;

    protected override void OnInitialized()
    {
        // Only fetch if not restored from prerender state
        notifications ??= NotificationService.GetNotifications();
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            // Start polling only after the component is interactive (never during prerender)
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(5000, ct).ConfigureAwait(false);

            // Simulate new data arriving server-side
            NotificationService.SimulateNewNotifications();

            var lastId = notifications?.Count > 0
                ? notifications.Max(n => n.Id)
                : 0;

            var newer = NotificationService.GetNotificationsSince(lastId);
            if (newer.Count > 0)
            {
                await InvokeAsync(() =>
                {
                    notifications ??= new();
                    notifications.AddRange(newer);
                    StateHasChanged();
                });
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

